def stmt(mod, name, n=8):
    p = os.path.join(KTX, mod + '.lean')
    if not os.path.exists(p): return 'AUSENTE'
    t = open(p, encoding='utf-8').read().split('\n')
    for i, l in enumerate(t):
        if re.match(r'^(theorem|def|noncomputable def|structure) %s\b' % re.escape(name), l):
            bloco = []
            for l2 in t[i:i + n]:
                bloco.append(l2)
                if ':= by' in l2 or l2.rstrip().endswith(':=') or l2.strip().endswith('where'): break
            return '\n'.join(bloco)
    return 'AUSENTE'
